/* Dependency-free illustrative terrain renderer; no external map calls or invented survey data. */
class TerrainView {
 constructor(canvas,options){this.canvas=canvas;this.ctx=canvas.getContext('2d');this.options=options;this.angle=-.53;this.zoom=1;this.mode='3d';this.drag=null;this.hit=[];this.time=12;this.layers={fire:true,assets:true,routes:true,wind:true,context:true};this.frame=0;this.resize=()=>{const b=canvas.getBoundingClientRect();this.w=b.width;this.h=b.height;const d=Math.min(devicePixelRatio||1,2);canvas.width=b.width*d;canvas.height=b.height*d;this.ctx.setTransform(d,0,0,d,0,0);this.draw()};this.observer=new ResizeObserver(this.resize);this.observer.observe(canvas);canvas.addEventListener('pointerdown',e=>{this.drag={x:e.clientX,y:e.clientY,angle:this.angle,moved:false};canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(this.drag){const delta=e.clientX-this.drag.x;if(Math.abs(delta)>4)this.drag.moved=true;if(this.mode==='3d'){this.angle=this.drag.angle+delta*.006;this.draw()}}});canvas.addEventListener('pointerup',e=>{if(this.drag&&!this.drag.moved){const b=canvas.getBoundingClientRect();const x=e.clientX-b.left,y=e.clientY-b.top;const found=this.hit.find(p=>Math.hypot(p.x-x,p.y-y)<24);if(found)this.options.onSelect(found.id)}this.drag=null});canvas.addEventListener('wheel',e=>{e.preventDefault();this.zoom=Math.max(.65,Math.min(1.8,this.zoom-e.deltaY*.0007));this.draw()},{passive:false});this.resize();}
 destroy(){this.observer.disconnect();cancelAnimationFrame(this.frame)}
 set(options){Object.assign(this.options,options);this.draw()}
 height(x,y){if(this.options.scenario.terrain==='urban')return .015;return .04+.26*Math.exp(-((x+.55)**2/.16+(y+.5)**2/.5))+.39*Math.exp(-((x-.62)**2/.12+(y+.65)**2/.22))+.2*Math.exp(-((x-.8)**2/.2+(y-.6)**2/.25))+.035*Math.sin(x*10+y*5)*Math.cos(y*8)*Math.exp(-y*y)}
 point(x,y,z=null){z=z??this.height(x,y);const flat=this.mode==='2d',angle=flat?0:this.angle;const rx=x*Math.cos(angle)-y*Math.sin(angle),ry=x*Math.sin(angle)+y*Math.cos(angle);const scale=Math.min(this.w*.37,this.h*.62)*this.zoom;return {x:this.w*.5+rx*scale,y:this.h*.56+ry*scale*(flat?.85:.56)-(flat?0:z*scale*.95),depth:ry,z}}
 line(points,color,width=1,dash=[]){const c=this.ctx;c.beginPath();points.forEach((p,i)=>{const v=this.point(...p);i?c.lineTo(v.x,v.y):c.moveTo(v.x,v.y)});c.strokeStyle=color;c.lineWidth=width;c.setLineDash(dash);c.stroke();c.setLineDash([])}
 polygon(points,fill,stroke=null){const c=this.ctx;c.beginPath();points.forEach((p,i)=>{const v=this.point(...p);i?c.lineTo(v.x,v.y):c.moveTo(v.x,v.y)});c.closePath();c.fillStyle=fill;c.fill();if(stroke){c.strokeStyle=stroke;c.lineWidth=.6;c.stroke()}}
 label(x,y,text,color='#aac1a4',offset=0){const p=this.point(x,y);const c=this.ctx;c.font='9px ui-sans-serif, sans-serif';const w=c.measureText(text).width;c.fillStyle='#14251ddd';c.fillRect(p.x-w/2-5,p.y+offset-10,w+10,17);c.fillStyle=color;c.textAlign='center';c.fillText(text,p.x,p.y+offset+2)}
 draw(){if(!this.w||!this.h)return;const c=this.ctx;c.clearRect(0,0,this.w,this.h);const scenario=this.options.scenario,urban=scenario.terrain==='urban';c.save();const grid=[];const n=34;for(let j=0;j<n;j++)for(let i=0;i<n;i++){const x=-1.12+i*2.24/n,y=-1.12+j*2.24/n,s=2.24/n;const h=this.height(x,y);grid.push({p:[[x,y],[x+s,y],[x+s,y+s],[x,y+s]],d:this.point(x,y).depth,h,x,y})}grid.sort((a,b)=>a.d-b.d);for(const q of grid){const shade=Math.floor(q.h*70+5*Math.sin(q.x*27)*Math.cos(q.y*23));this.polygon(q.p,urban?`rgb(${37+shade},${51+shade},${47+shade})`:`rgb(${34+shade*.55},${58+shade*.85},${43+shade*.55})`,'#64805b19')}
 // A bounded demonstration surface, not a geographic boundary.
 this.line([[-1.12,-1.12],[1.12,-1.12],[1.12,1.12],[-1.12,1.12],[-1.12,-1.12]],'#6b87634f',1);
 if(this.layers.context){if(urban)this.city();else this.forest();}
 if(this.layers.routes){const points=[[-.8,.7],[-.55,.36],[-.2,.25],[.13,-.06],[.4,-.3],[.75,-.44]];this.line(points,'#c6c09a80',3);this.line(points,'#65755b',1,[4,5]);this.line([[-.7,-.4],[-.5,-.3],[-.15,-.22],[.13,-.06],[.38,.12],[.52,.56]],'#a2d2d5aa',1.4,[5,5]);}
 this.hit=[];
 if(this.layers.fire){scenario.incidents.forEach((inc,index)=>{const chosen=inc.id===this.options.selected;const step=Math.floor(this.time/20);const radius=(index===0?.075+step*.018:.036);const pts=[];for(let i=0;i<=32;i++){const a=i/32*Math.PI*2,r=radius*(1+.18*Math.sin(a*5+index)+.15*Math.cos(a*3));pts.push([inc.x+Math.cos(a)*r*1.6,inc.y+Math.sin(a)*r])}this.polygon(pts,chosen?'#db7b3d55':'#b8773e33',chosen?'#f6b16e':'#b88950');this.line([...pts,pts[0]],chosen?'#f1ac6b':'#a87946',chosen?1.6:1);if(chosen&&step>0){const inner=pts.map(p=>[inc.x+(p[0]-inc.x)*.6,inc.y+(p[1]-inc.y)*.6]);this.line(inner,'#f7cc9055',1,[3,3])}const p=this.point(inc.x,inc.y,this.height(inc.x,inc.y)+.035);c.beginPath();c.arc(p.x,p.y,chosen?6:4,0,Math.PI*2);c.fillStyle=chosen?'#ffc18c':'#d8905c';c.shadowColor='#ed9755';c.shadowBlur=chosen?16:4;c.fill();c.shadowBlur=0;c.beginPath();c.arc(p.x,p.y,chosen?16:10,0,Math.PI*2);c.strokeStyle=chosen?'#f5b37c99':'#bb855c66';c.lineWidth=1;c.stroke();this.hit.push({id:inc.id,x:p.x,y:p.y});if(chosen){c.textAlign='left';c.font='10px ui-sans-serif,sans-serif';const text=inc.id+'  ·  '+(scenario.code==='MUM'?'REFERENCE':'SIMULATED');const tw=c.measureText(text).width;c.fillStyle='#342b20ec';c.fillRect(p.x+18,p.y-21,tw+18,24);c.strokeStyle='#a67a48';c.strokeRect(p.x+18,p.y-21,tw+18,24);c.fillStyle='#edc89e';c.fillText(text,p.x+27,p.y-6);c.beginPath();c.moveTo(p.x+6,p.y-3);c.lineTo(p.x+18,p.y-9);c.stroke()}})}
 if(this.layers.assets){scenario.fleet.forEach((asset,index)=>{let x=asset.x,y=asset.y;if(index===0){const t=this.time/100;x=asset.x+t*.48;y=asset.y+t*.24}const p=this.point(x,y,this.height(x,y)+.15);const ground=this.point(x,y);c.strokeStyle='#a6cdd34f';c.setLineDash([2,4]);c.beginPath();c.moveTo(p.x,p.y);c.lineTo(ground.x,ground.y);c.stroke();c.setLineDash([]);c.fillStyle='#a9d3d7';c.strokeStyle='#b7e0e1';c.lineWidth=1.5;c.beginPath();c.moveTo(p.x-6,p.y-6);c.lineTo(p.x+6,p.y+6);c.moveTo(p.x+6,p.y-6);c.lineTo(p.x-6,p.y+6);c.stroke();for(const dx of [-6,6])for(const dy of [-6,6]){c.beginPath();c.ellipse(p.x+dx,p.y+dy,4,2,0,0,Math.PI*2);c.stroke()}c.fillRect(p.x-2,p.y-3,4,6);c.font='8px ui-sans-serif,sans-serif';c.textAlign='center';c.fillStyle='#b7d5d4';c.fillText(scenario.code==='MUM'?'AIRCRAFT REFERENCE':asset.id,p.x,p.y-14)})}
 if(this.layers.wind&&scenario.code!=='MUM'){c.save();c.translate(this.w-105,this.h-78);c.strokeStyle='#9fbea899';c.fillStyle='#b7c9ab';c.lineWidth=1;for(let i=0;i<3;i++){c.beginPath();c.moveTo(-15,i*8);c.lineTo(19,i*8-16);c.lineTo(11,i*8-15);c.moveTo(19,i*8-16);c.lineTo(16,i*8-9);c.stroke()}c.font='8px ui-sans-serif,sans-serif';c.textAlign='center';c.fillText(scenario.wind+' km/h · SIM',0,40);c.restore()}
 c.restore();}
 forest(){const c=this.ctx;const water=[];for(let i=0;i<=60;i++){const y=-1.1+i*2.2/60;water.push([-.66+.09*Math.sin(y*4)+y*.11,y])}this.line(water,'#446d66',10);this.line(water,'#709a8a55',5);for(let i=0;i<150;i++){const x=Math.sin(i*43.1)*1.02,y=Math.cos(i*17.4)*1.04;if(Math.abs(x-(-.66+.09*Math.sin(y*4)+y*.11))<.07)continue;const p=this.point(x,y);const hh=this.mode==='2d'?2:4+(i%4);c.fillStyle=i%3===0?'#637d51a0':'#375b3c';c.beginPath();c.moveTo(p.x,p.y-hh);c.lineTo(p.x-2.7,p.y+1);c.lineTo(p.x+2.7,p.y+1);c.closePath();c.fill()}this.label(-.78,.74,'ACCESS POINT','#bbccaa',17);this.label(.68,-.85,'RIDGE SECTOR','#a2b993',0);this.label(.72,.68,'SETTLEMENT EDGE','#bac6a5',19);for(let i=0;i<5;i++)this.building(.6+i*.035,.68+(i%2)*.06,.028,.03,.025);}
 building(x,y,w,d,h){const z=this.height(x,y);const base=[[x,y,z],[x+w,y,z],[x+w,y+d,z],[x,y+d,z]],top=base.map(p=>[p[0],p[1],p[2]+h]);if(this.mode==='3d'){this.polygon([base[1],base[2],top[2],top[1]],'#52635a','#778778');this.polygon([base[2],base[3],top[3],top[2]],'#3f5048','#71816e')}this.polygon(top,'#778375','#919a86');}
 city(){for(let i=-4;i<=4;i++){const p=i*.23;this.line([[-1.08,p],[1.08,p]],'#a7ad8d55',7);this.line([[p,-1.08],[p,1.08]],'#a7ad8d55',7);this.line([[-1.08,p],[1.08,p]],'#c2be9a55',.7,[4,8]);this.line([[p,-1.08],[p,1.08]],'#c2be9a55',.7,[4,8])}const blocks=[];for(let i=-4;i<4;i++)for(let j=-4;j<4;j++){if((i===0&&j===0)||(i===-1&&j===2))continue;blocks.push({x:i*.23+.045,y:j*.23+.045,w:.12,d:.13,h:.04+((i*j+17)%5)*.025,depth:this.point(i*.23,j*.23).depth})}blocks.sort((a,b)=>a.depth-b.depth);blocks.forEach(b=>this.building(b.x,b.y,b.w,b.d,b.h));this.label(-.67,.78,'RESPONSE STATION','#bdcbaa',20);this.label(.7,-.7,'COMMERCIAL BLOCKS','#bdcbaa',0);}
}
